   112	    private static class LongestStagePerJobProcessFunction
   113	            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {
   114	
   115	        private final long inactivityGapMicros;
   116	
   117	        private transient ValueState<Long> lastSubmitTsMicros;
   118	        private transient ValueState<Integer> currentStageCount;
   119	        private transient ValueState<Integer> longestStageCount;
   120	        private transient ValueState<Long> inactivityTimerTsMicros;
   121	
   122	        LongestStagePerJobProcessFunction(long inactivityGapMicros) {
   123	            this.inactivityGapMicros = inactivityGapMicros;
   124	        }
   125	
   126	        @Override
   127	        public void open(Configuration parameters) {
   128	            lastSubmitTsMicros = getRuntimeContext().getState(new ValueStateDescriptor<>(
   129	                    "lastSubmitTsMicros", Long.class));
   130	            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>(
   131	                    "currentStageCount", Integer.class));
   132	            longestStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>(
   133	                    "longestStageCount", Integer.class));
   134	            inactivityTimerTsMicros = getRuntimeContext().getState(new ValueStateDescriptor<>(
   135	                    "inactivityTimerTsMicros", Long.class));
   136	        }
   137	
   138	        @Override
   139	        public void processElement1(TaskEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
   140	            if (!value.isSubmit()) {
   141	                return;
   142	            }
   143	
   144	            Integer cur = currentStageCount.value();
   145	            if (cur == null) {
   146	                cur = 0;
   147	            }
   148	
   149	            long ts = value.getTimestampMicros();
   150	            Long lastTs = lastSubmitTsMicros.value();
   151	
   152	            if (lastTs == null) {
   153	                cur = 1;
   154	            } else {
   155	                long gap = ts - lastTs;
   156	                if (gap > inactivityGapMicros) {
   157	                    finalizeCurrentStage();
   158	                    cur = 1;
   159	                } else {
   160	                    cur = cur + 1;
   161	                }
   162	            }
   163	
   164	            lastSubmitTsMicros.update(ts);
   165	            currentStageCount.update(cur);
   166	
   167	            // schedule/refresh the inactivity timer
   168	            Long prevTimer = inactivityTimerTsMicros.value();
   169	            if (prevTimer != null) {
   170	                ctx.timerService().deleteEventTimeTimer(prevTimer);
   171	            }
   172	            long newTimer = ts + inactivityGapMicros;
   173	            inactivityTimerTsMicros.update(newTimer);
   174	            ctx.timerService().registerEventTimeTimer(newTimer);
   175	        }
   176	
   177	        @Override
   178	        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
   179	            Long expected = inactivityTimerTsMicros.value();
   180	            if (expected == null || expected != timestamp) {
   181	                return;
   182	            }
   183	
   184	            finalizeCurrentStage();
   185	            inactivityTimerTsMicros.clear();
   186	            lastSubmitTsMicros.clear();
   187	            currentStageCount.clear();
   188	        }
   189	
   190	        @Override
   191	        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
   192	            if (!value.isTerminal()) {
   193	                return;
   194	            }
   195	
   196	            // If the job ends before the inactivity timer fires, finalize the active stage.
   197	            finalizeCurrentStage();
   198	
   199	            Integer best = longestStageCount.value();
   200	            if (best == null) {
   201	                best = 0;
   202	            }
   203	            out.collect(Tuple2.of(ctx.getCurrentKey(), best));
   204	
   205	            Long timer = inactivityTimerTsMicros.value();
   206	            if (timer != null) {
   207	                ctx.timerService().deleteEventTimeTimer(timer);
   208	            }
   209	
   210	            lastSubmitTsMicros.clear();
   211	            currentStageCount.clear();
   212	            longestStageCount.clear();
   213	            inactivityTimerTsMicros.clear();
   214	        }
   215	
   216	        private void finalizeCurrentStage() throws Exception {
   217	            Integer cur = currentStageCount.value();
   218	            if (cur == null) {
   219	                cur = 0;
   220	            }
   221	
   222	            Integer best = longestStageCount.value();
   223	            if (best == null) {
   224	                best = 0;
   225	            }
   226	
   227	            if (cur > best) {
   228	                longestStageCount.update(cur);
   229	            }
   230	        }

